# The Signature collider-chooser rubric (educational, labeled)
def choose(goal):
    table = {"new particle": "hadron ring: max CM energy (LHC/FCC-hh pattern)",
             "precision coupling": "lepton factory: max luminosity at resonance",
             "nuclear matter": "heavy-ion collider: max energy density",
             "proton structure": "electron-ion collider: polarized, asymmetric"}
    return table.get(goal, "no recommendation")
for g in ["new particle", "precision coupling", "nuclear matter", "proton structure"]:
    print("%-18s -> %s" % (g, choose(g)))

# Versatility vs optimization: RHIC and LHC payoffs (Signature comparison)
payoffs = {"RHIC (versatile)": ["perfect-liquid QGP", "proton spin puzzle", "species scan"],
           "LHC (optimized)": ["Higgs boson", "precision SM", "rare processes"]}
for m, ps in payoffs.items():
    print(m)
    for p in ps:
        print("   -", p)
print("Signature lesson: design the portfolio, not just the machine")
